<span class="line"><span style="color:#24292E">  lenis.</span><span style="color:#6F42C1">raf</span><span style="color:#24292E">(time);</span></span>
<span class="line"><span style="color:#6F42C1">  requestAnimationFrame</span><span style="color:#24292E">(raf);</span></span>
